insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('d69facab-2ffb-5530-a91a-9bcde0f40f7c', 'bo_tro', null, '43ef2417-2b47-525a-aaa0-22c43701b2e5', 'BT7', 'Trả nghiệp', 'Chủ động trả trước cho nghiệp đã tạo nhưng chưa đổ về — <em>trích 1 đồng ra trả trước, tránh khi họa đổ về thì mất cả 100 đồng</em>', null, null, '{"loai_bt":"Khuôn có chu kỳ","khi":"3 tháng/lần","di":{"che":"khuon","nhan":"Khuôn 03 trong Thư viện khuôn"}}'::jsonb, 6, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('71e83da1-56b5-5766-8e0e-36867a0d3889', 'bo_tro', null, '43ef2417-2b47-525a-aaa0-22c43701b2e5', 'BT8', 'Tu tập', 'Tu tập khác kính lễ — tu tập là cầu nguyện sáng tối, sám hối 4 mùa cho người sống, mùa Vu lan báo hiếu', null, null, '{"loai_bt":"Khuôn có chu kỳ","khi":"Hằng ngày (cầu nguyện sáng tối) · 4 mùa (sám hối) · tháng 5–6–7 âm (Vu lan)","di":{"che":"khuon","nhan":"Khuôn 01 trong Thư viện khuôn"}}'::jsonb, 7, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('d9ae2a1e-fb9e-5a19-94a3-6b69170f9563', 'bo_tro', null, '43ef2417-2b47-525a-aaa0-22c43701b2e5', 'BT9', 'Hướng dẫn sử dụng Công thức học', '4 cột: Nhận ra → Quy chuẩn → Quy chiếu → Ứng dụng (hướng đi). Dùng ngược lại để xây hướng đi cho bản thân, gia đình, con cái, công việc, tài chính', null, null, '{"loai_bt":"Công cụ","khi":"Mỗi lần học một ý Trí tuệ mới","di":{"che":"lotrinh","nhan":"Mục Công thức học ngay bên dưới"}}'::jsonb, 8, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('999a0883-6846-50ae-a44b-577feb7ef127', 'bo_tro', null, '43ef2417-2b47-525a-aaa0-22c43701b2e5', 'BT10', 'Giải quyết vấn đề bất ổn', '<b>Công thức ứng dụng Trí tuệ + Công thức giải cảnh</b> — pháp hóa giải, trực chỉ vào góc độ tác động chính', null, null, '{"loai_bt":"Công cụ","khi":"Khi có cảnh đổ về","di":{"che":"wizard","nhan":"Chế độ Có vấn đề bất ổn"}}'::jsonb, 9, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('459d6ed6-ba30-5f90-a527-2a818010808c', 'bo_tro', null, '43ef2417-2b47-525a-aaa0-22c43701b2e5', 'BT11', 'Hằng ngày viết đưa khuôn Trí tuệ vào cuộc sống', '<b>Công thức sử dụng Trí tuệ + Công thức đối cảnh</b> — pháp xoay chuyển, làm cho tất cả các nhóm, để dừng nghiệp', null, null, '{"loai_bt":"Công cụ","khi":"Mỗi ngày — tối lập kế hoạch cho ngày mai","di":{"che":"hangngay","nhan":"Chế độ Sống hằng ngày"}}'::jsonb, 10, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('c92ea408-b2ba-5a4e-8104-80d6f072f298', 'nhom_hoc', null, '43ef2417-2b47-525a-aaa0-22c43701b2e5', 'NH1', 'Vừa nắm được tổng quan, vừa nắm được chi tiết', 'Dùng app như sổ tra cứu — vào thẳng Cây kiến thức và Thư viện khuôn.', null, null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('f5ade727-7cf9-525e-837b-a53bcc8c40cf', 'nhom_hoc', null, '43ef2417-2b47-525a-aaa0-22c43701b2e5', 'NH2', 'Nắm được tổng quan nhưng không học chi tiết', 'Bắt đầu từ Thư viện khuôn — làm trước, hiểu sau. Mỗi khuôn có phần <em>nhận ra gì mà ứng dụng</em> để bù phần chi tiết.', null, null, '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('0b373fdb-a511-5656-9284-152e8aa48085', 'nhom_hoc', null, '43ef2417-2b47-525a-aaa0-22c43701b2e5', 'NH3', 'Không nắm được tổng quan, chỉ học được chi tiết từng ý nhưng rất chậm', 'Đọc Lộ trình này trước để có bức tranh, rồi mới vào Cây kiến thức. Đây là nhóm bản dựng này phục vụ chính.', null, null, '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('ae7aa5af-6866-5d5f-9d83-cfa9b8f3ce79', 'nhom_hoc', null, '43ef2417-2b47-525a-aaa0-22c43701b2e5', 'NH4', 'Không nắm được tổng quan, chỉ nắm được một số ý đang cần', 'Vào thẳng chế độ Có vấn đề bất ổn — giải xong một việc thật rồi sẽ có động lực học tiếp.', null, null, '{}'::jsonb, 3, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('90ec6cf6-a89d-5c1d-abf2-5d237a71e7bc', 'cong_thuc_hoc', null, '43ef2417-2b47-525a-aaa0-22c43701b2e5', null, 'Nhận ra', 'Viết <b>cốt</b> — tên ý mình nhận được', null, null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('28f5135d-da45-5988-9f23-d897f9973085', 'cong_thuc_hoc', null, '43ef2417-2b47-525a-aaa0-22c43701b2e5', null, 'Quy chuẩn', 'Viết <b>cốt của cốt</b> — đủ câu, đủ ý, đủ nghĩa, đủ từ: ý này chỉ cho ta biết gì và cần làm gì?', null, null, '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
