insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('17c052c2-1cf9-521e-a5dd-bceef0050987', 'chu_ky', null, 'f21071a0-cd7a-5f89-be5f-de5d7e436dd0', null, 'Tháng 5–6–7 âm', null, null, null, '{"viec":["Tháng 5: Lương hoàng sám","Tháng 6: kinh Địa tạng","Tháng 7: Nghi thức cầu siêu · khao gia tiên trước rằm · cầu siêu rằm tháng 7"]}'::jsonb, 5, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
