insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('480c1123-d7a5-5862-bb2c-ea59de7f94fd', 'phan_xa', null, 'f21071a0-cd7a-5f89-be5f-de5d7e436dd0', 'nguoi', 'Với CON NGƯỜI', null, null, null, '{"buoc":["Xét <b>tâm trạng của họ lúc đó</b> — mỗi người mỗi thời điểm mỗi khác","Xét người → Thấu triệt → Đúng nguyên lý → Chuẩn Đạo → Đúng 5 luật","Hành xử và đối nhân xử thế chuẩn mực","Triệt để: <b>tròn tâm · tròn đạo · tròn việc · tròn nhân duyên</b>"]}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('4b61ad13-593a-54f4-bb9a-d838e3923839', 'phan_xa', null, 'f21071a0-cd7a-5f89-be5f-de5d7e436dd0', 'viec', 'Với SỰ VIỆC', null, null, null, '{"buoc":["Việc đó ta đã <b>đủ nhân duyên và phúc đức</b> chưa? Chưa đủ thì <b>thêm thời gian để bồi</b>, không làm ngay","Xét <b>Đích</b> của việc đó — <b>đáng mới làm</b>","Thấu triệt sự việc → Đúng nguyên lý → Chuẩn Đạo → Đúng 5 luật","<b>Đúng</b>: đúng thời điểm, đúng khuôn. <b>Đủ</b>: đủ phúc đức, đủ thời gian, bám đủ 14 ý"]}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('91c1c948-004e-5b6e-80c4-85dc19aaf8ce', 'canh_phat_sinh', null, 'f21071a0-cd7a-5f89-be5f-de5d7e436dd0', null, 'Cảnh phá Tâm Bồ Đề', 'Người ta mời mình, cho mình tiền bạc, danh lợi, vị trí cao hơn — để kéo mình rời khỏi con đường Hành sứ mệnh; hoặc rủ mình theo một con đường Đạo khác', '<b>Không cần danh lợi và vị trí</b> thì mới thoát được cảnh. Đích của ta chỉ là <b>Tu Luyện</b>.', null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('d2d1a408-3c9b-58b8-8381-6d0e7d0df6d0', 'canh_phat_sinh', null, 'f21071a0-cd7a-5f89-be5f-de5d7e436dd0', null, 'Cảnh chướng cản từ người thân', 'Bố mẹ, người thân chướng cản, không liên quan danh lợi, khiến kế hoạch không thực hiện tiếp được', '<b>Lấy vốn từ ra để đặt tên cảnh</b>: cảnh này ta đang nợ họ bằng <b>công</b> hay bằng <b>của</b>? → tạo phúc trả nợ bằng công hoặc của cho họ. <b>Trả đủ rồi mới làm được việc của mình.</b>', null, '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
