insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('e9b541af-1c2f-538f-8889-18f5a6c1e0ec', 'bieu_hien', null, '06e9a0ed-f4ef-5780-8fbf-e0900264def0', 'BH3', 'Trong nhà lục đục, rối ren; gia tiên hình như không về được', 'Thờ tự không chuẩn nên không được các Thần trông nom, các vong khác vào được', null, null, '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
