insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('0bb3b5df-7905-5d59-805d-c03518676969', 'goc_do', null, '06e9a0ed-f4ef-5780-8fbf-e0900264def0', 'khuyetduc', 'Khuyết đức → mất phần', 'Tổng hợp của hành xử kém + lỗi đạo + lỗi Hiếu–Lễ–Nghĩa, dẫn đến mất phần và mất nhân duyên', null, null, '{}'::jsonb, 9, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('68b25912-dae9-599c-823b-64a077896a1f', 'phap', null, '06e9a0ed-f4ef-5780-8fbf-e0900264def0', 'doitri', 'Pháp đối trị', 'Trả nghiệp trước để việc mình định làm không bị chướng cản.', null, null, '{"khi":"Luôn đi trước","lam":["Tạo phúc, trả nợ trước · hồi hướng công đức trước · phóng sinh trước — cho những vong linh và người trần liên quan trực tiếp đến việc mình định triển khai","Nói chuyện trước với người có liên quan để họ hiểu giá trị việc mình làm","<em>Lưu ý: không đối trị với những người không liên quan — sẽ khiến họ tưởng mình có quyền can thiệp và gây chướng cản</em>"]}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('5a4a8dc5-455c-51de-bbe6-15c1c415e658', 'phap', null, '06e9a0ed-f4ef-5780-8fbf-e0900264def0', 'hoagiai', 'Pháp hóa giải', 'Hóa giải trực chỉ vào góc độ tác động chính khi cảnh đã đổ về.', null, null, '{"khi":"Song song","lam":["Đọc sám · phóng sinh · hồi hướng công đức · tạo phúc trả nợ — <b>trực tiếp cho góc độ tác động chính</b>","Khi mình làm sai khiến người khác bực tức thì phải xin lỗi","Làm <b>liên tục</b> cho đến khi hết bất ổn thì thôi"]}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('a5b6fdc8-1d52-563d-a34e-79af0c4a08a7', 'phap', null, '06e9a0ed-f4ef-5780-8fbf-e0900264def0', 'xoaychuyen', 'Pháp xoay chuyển', 'Đưa khuôn Trí tuệ vào cuộc sống để dừng nghiệp.', null, null, '{"khi":"Song song","lam":["Ứng dụng các khuôn Trí tuệ trong từng việc, cho <b>tất cả các nhóm</b> — người trần và mọi nhóm vong linh","Chuyển từ cuộc sống thói thường trước đây sang cuộc sống có Trí tuệ","Không chờ hết bất ổn mới làm — chạy song song với pháp hóa giải"]}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
