insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('64acd0b9-0f1e-57b0-a1b2-785629b50906', 'phan', null, '486cdc6d-3902-5eb6-ae1e-991b35918e15', 'P11', 'Kế thừa cho thế hệ tương lai', 'Truyền lại cho con cháu và nhân loại thế nào?', null, null, '{}'::jsonb, 11, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('b63445aa-df4c-5b98-ba98-9741748c2748', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'thocung', 'Thờ cúng chuẩn – Kính lễ – Tu tập', '<b>NLCĐ 1</b> — ta là con Trời con Phật nên cần bái yết Cha Mẹ và các Ngài hằng ngày để <b>Cha biết mặt, Mẹ biết tên</b>, các Ngài cho các thần đi hộ trì, độ trì. <b>NLCĐ 2</b> — ta sinh ra để tu tiếp, trong đó có tu tập. <b>NLCĐ 8</b> — ứng dụng này báo ơn được <b>cả 5 điểm tựa</b> cùng lúc. <b>7 Đạo</b> — tròn 7 đạo để lập đức, giữ phần. <b>Ý pháp oan gia</b> — hóa giải oan gia trái chủ.', null, null, '{"so":1,"nhom":"Nền tảng tâm linh","giai":["Lỗi Hiếu–Lễ–Nghĩa","Thờ tự gia tiên","Vô tâm với Trời Phật và Gia tiên"],"bam":["dao","dungluat","trong","tamtubi"],"chu_ky":"Hằng ngày · hằng tháng"}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('ae4cb368-4754-5de8-b07e-8020d49b4a72', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'taophuc', 'Tạo phúc, trả nợ', '<b>NLCĐ 2</b> — ta sinh ra để trả nghiệp. <b>NLCĐ 8</b> — báo ơn được 5 điểm tựa. <b>Ý pháp oan gia trái chủ</b> — hóa giải oan gia. <b>Ý pháp nợ công, nợ của</b> — trả nợ và <b>dừng không tạo ra các nợ mới</b>.', null, null, '{"so":2,"nhom":"Xử lý nghiệp","giai":["Nợ công, nợ của người trần","Tâm linh — gia tiên và các nhóm vong","Hóa giải oan gia","Phúc đức cạn"],"bam":["goc","nguyentac","trong","tamtubi"],"chu_ky":"6 tháng/lần"}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('0f84ee29-94bd-5414-9211-2a3e4cfaeb40', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'tranghiep', 'Trả nghiệp', 'Trả nghiệp là <b>chủ động trả trước</b> cho những nghiệp đã tạo ra nhưng chưa đổ về. <em>“Trả nghiệp là Gốc — trả không hết để nghiệp đổ về thì mới phải giải nghiệp.”</em> Giải nghiệp mới chỉ là bề nổi; tảng băng chìm là nghiệp vô thủy kiếp trước tích lại.', null, null, '{"so":3,"nhom":"Xử lý nghiệp","giai":["Nghiệp đổ về","Oan gia trái chủ","Phúc đức cạn"],"bam":["yphap","goc","nguyentac","congthuc"],"chu_ky":"3 tháng/lần"}'::jsonb, 3, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('769b7fd2-eba9-53c6-9bb4-6f0990c1adcc', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'giainghiep', 'Giải nghiệp', 'Không ai giải nghiệp thay mình được. 4 bước: <b>Dừng nghiệp → Hóa nghiệp → Đón nghiệp → Chuyển nghiệp</b>.', null, null, '{"so":4,"nhom":"Xử lý nghiệp","giai":["Nghiệp đổ về","Oan gia trái chủ","Tâm linh"],"bam":["yphap","thucte","congthuc","trietde"],"chu_ky":"Khi có cảnh · 4 mùa"}'::jsonb, 4, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('331e2fef-eeb2-5aef-bbe7-ad21cd0bfa65', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'dungnghiep', 'Dừng nghiệp', '<b>NLCĐ 2</b> — nghiệp sinh ra từ việc không đưa Trí tuệ vào lợi tư. Muốn dừng thì phải <b>dám đối diện</b> với những việc mình đã làm sai và <b>xác định làm lại từ đầu</b>.', null, null, '{"so":5,"nhom":"Xử lý nghiệp","giai":["Nghiệp đổ về","Nợ công, nợ của"],"bam":["nguyenly","goc","trietde","congthuc"],"chu_ky":"Hằng ngày"}'::jsonb, 5, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('582cf0fd-c055-5813-b388-53abf1626962', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'sumenh', 'Hành sứ mệnh', 'Hành sứ mệnh <b>Lan tỏa Trí tuệ là công đức lớn nhất</b>. Đích: báo Tứ đại trọng ơn · giữ chân mệnh · cống hiến vô danh vô lợi · tạo phúc trả nợ báo ơn báo hiếu · hóa giải ân oán · luyện Trí tuệ.', null, null, '{"so":6,"nhom":"Cống hiến","giai":["Nợ công người trần","Hóa giải oan gia","Phúc đức cạn","Nợ công, nợ của"],"bam":["nguyenly","goc","congthuc","dao","trong","tron","trietde"],"chu_ky":"Theo kế hoạch Đời"}'::jsonb, 6, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('9c5624a0-daa2-5c4e-b5fa-9dc6e1633532', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'hanhxu', 'Hành xử', '<b>NLCĐ 1</b> — là con Trời con Phật nên phải hành xử chuẩn mực để giữ <b>cốt cách thanh cao</b>. <b>NLCĐ 2</b> — hành xử chuẩn để <b>dừng nghiệp, không tạo nghiệp mới</b>. <b>7 Đạo</b> — tròn 7 đạo để lập đức, giữ phần. <b>Ý pháp oan gia</b> — <b>không tạo ra</b> oan gia trái chủ mới.', null, null, '{"so":7,"nhom":"Đối nhân","giai":["Lỗi đạo","Hành xử kém","Vô nguyên tắc","Khuyết đức → mất phần"],"bam":["nguyenly","dao","nguyentac","quyluat","kiemsoat","thautriet"],"chu_ky":"Mọi lúc"}'::jsonb, 7, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('ca02cfe5-453f-5c7e-811c-ce9d3e7c9c4a', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'dnxt', 'Đối nhân xử thế', '<b>Đối nhân</b> = đối xử · đối đáp · đối đãi. <b>Xử thế</b> = xử lý tình huống. Cần bám vào Trí tuệ và quy luật tự nhiên — mọi việc đều định vị bởi <b>Nhân quả – Phúc đức – Nhân duyên</b>.', null, null, '{"so":8,"nhom":"Đối nhân","giai":["Lỗi đạo","Hành xử kém","Vô nguyên tắc"],"bam":["nguyenly","dao","quyluat","xetnguoi","tamtubi"],"chu_ky":"Mọi lúc"}'::jsonb, 8, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('754a5dd6-543a-5802-b80e-f84455a11f65', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'lamtt', 'Làm Trí tuệ', '<b>NLCĐ 2 · Nghiệp đời</b> — làm không tròn tâm, tròn đạo, tròn việc, tròn nhân duyên thì tạo nghiệp đời. Làm Trí tuệ là để dừng nghiệp đời ngay trong lúc làm.', null, null, '{"so":9,"nhom":"Làm việc & thời gian","giai":["Hành xử kém","Nghiệp đổ về"],"bam":["nguyenly","dao","nguyentac","trietde","thautriet","congthuc"],"chu_ky":"Mỗi việc"}'::jsonb, 9, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('32dc7199-d8db-514f-872b-075bca8b9e71', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'ddlt', 'Lập kế hoạch thời gian Đời – Đạo – Lợi tư', '<b>NLCĐ 2</b> — ta sinh ra làm 3 việc, ứng với <b>3 công trình</b> Đời – Đạo – Lợi tư. <b>Đạo Sinh</b> — lập kế hoạch thời gian để tròn Đạo Sinh. Quan trọng nhất: <b>có thời gian để Hành sứ mệnh thì mới có phúc đức và công đức</b>.', null, null, '{"so":10,"nhom":"Làm việc & thời gian","giai":["Phúc đức cạn","Nghiệp đổ về"],"bam":["nguyentac","thucte","congthuc"],"chu_ky":"Hằng tuần"}'::jsonb, 10, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('364d2212-f16b-54a2-b049-6306879ce928', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'tron4', 'Tròn chức năng, vai trò, bổn phận, trách nhiệm', '<b>NLCĐ 2</b> — sinh ra để trả nghiệp; cần tròn 4 thứ trong gia đình và trong công việc để <b>dừng và trả nợ đời, nghiệp đời</b>. <b>NLCĐ 8</b> — tròn 4 thứ để báo ơn điểm tựa gia đình và điểm tựa đất nước.', null, null, '{"so":11,"nhom":"Làm việc & thời gian","giai":["Nợ công, nợ của","Hành xử kém","Lỗi đạo","Nghiệp đổ về"],"bam":["dao","trietde","tron","tamtubi"],"chu_ky":"Hằng ngày"}'::jsonb, 11, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('c4cafd61-fc2e-58f3-ac37-542442b25399', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'giugioi', 'Giữ giới, giữ hạnh', 'Giữ 5 giới và 18 hạnh là <b>Giới luật</b> — một trong 5 luật của Đạo Luật. Không giữ thì lỗi đạo, khuyết đức, mất phần.', null, null, '{"so":12,"nhom":"Giữ mình","giai":["Lỗi đạo","Vô nguyên tắc","Khuyết đức → mất phần"],"bam":["dungluat","dao","nguyentac"],"chu_ky":"Mọi lúc"}'::jsonb, 12, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('411f5633-42c4-56d5-bcac-0b6c380122f2', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'supháp', 'Sử dụng pháp', 'Nhận diện được <b>cảnh nào</b> thì mới dùng đúng <b>pháp nào</b>. Nhận nhầm cảnh thì dùng sai pháp, càng làm càng bất ổn.', null, null, '{"so":13,"nhom":"Xử lý nghiệp","giai":["Nghiệp đổ về","Oan gia trái chủ","Tâm linh"],"bam":["yphap","thucte","goc","congthuc"],"chu_ky":"Khi có cảnh"}'::jsonb, 13, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('d06b2d0d-0c59-5e2e-992d-aa303e06ba94', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'bode', 'Phát tâm bồ đề', 'Chủ động phát tâm bồ đề chính là đang <b>luyện trong sống để vượt qua chính bản thân mình</b> — vượt qua chữ tôi, sự lười biếng, sự bao biện.', null, null, '{"so":14,"nhom":"Cống hiến","giai":["Phúc đức cạn","Nợ công, nợ của"],"bam":["tamtubi","kiemsoat","trong","tron"],"chu_ky":"Mọi lúc, mọi nơi"}'::jsonb, 14, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('73356b29-280c-51cb-82df-8bd79c3a8957', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'suadoi', 'Sống cần sửa', '<b>Sửa đến đâu thì thói thường mất đi đến đó · sửa đến đâu thì phúc đức tăng lên đến đó.</b>', null, null, '{"so":15,"nhom":"Giữ mình","giai":["Hành xử kém","Vô nguyên tắc","Nghiệp đổ về"],"bam":["nguyenly","dao","kiemsoat","nguyentac"],"chu_ky":"Hằng ngày"}'::jsonb, 15, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('6a5cc675-f7e8-5f89-9cd6-ff134bff488c', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'thautriet', 'Thấu triệt', '<b>NLCĐ 5 Kiểm soát</b> — <b>thấu triệt thì mới kiểm soát được</b>: thấu triệt con người mới kiểm soát được quan hệ, thấu triệt công việc mới kiểm soát được công việc. <b>Tâm từ bi</b> — thấu triệt bản thân và người khác thì mới yêu thương, giúp đỡ được.', null, null, '{"so":16,"nhom":"Đối nhân","giai":["Hành xử kém","Vô nguyên tắc"],"bam":["kiemsoat","tamtubi","thucte","xetnguoi"],"chu_ky":"Trước mỗi việc"}'::jsonb, 16, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('3b675b24-0a8c-568c-a288-4b3537a82476', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'hln', 'Tròn Hiếu – Lễ – Nghĩa', 'Tròn Hiếu–Lễ–Nghĩa là điều kiện để giữ được <b>mạch nguồn phúc đức</b> ông bà để lại — <em>ĐỨC LƯU QUANG</em>.', null, null, '{"so":17,"nhom":"Giữ mình","giai":["Lỗi Hiếu – Lễ – Nghĩa","Tâm linh","Khuyết đức → mất phần"],"bam":["dao","trong","dungluat","tamtubi"],"chu_ky":"Hằng ngày · theo mùa"}'::jsonb, 17, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('0916f259-87f0-58b1-b4c4-dfbfc41978d8', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'nhantam', 'Sống có nhân tâm với con người và vạn vật', '<b>Đạo Tình</b> — vạn vật đều có linh, đều do các Ngài hóa hiện. Sống vô tâm với vạn vật là lỗi đạo tình.', null, null, '{"so":18,"nhom":"Đối nhân","giai":["Lỗi đạo","Khuyết đức → mất phần"],"bam":["dao","tamtubi","trong","thautriet"],"chu_ky":"Hằng ngày"}'::jsonb, 18, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('242c2f97-1508-54ff-b854-e34927ad16e0', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'giaquy', 'Sống đúng gia quy', '<b>Đạo Luật</b> gồm 5 luật và <b>GIA QUY</b>. Rất nhiều bất ổn về Hiếu–Lễ–Nghĩa bắt nguồn từ việc làm sai gia quy mà không biết.', null, null, '{"so":19,"nhom":"Giữ mình","giai":["Lỗi Hiếu – Lễ – Nghĩa","Tâm linh"],"bam":["dao","dungluat","nguyentac"],"chu_ky":"Khi nhà có việc"}'::jsonb, 19, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('8c2c3399-498f-5a91-8f59-770db0b5e50f', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'hoctt', 'Học Trí tuệ', 'Học đến đâu <b>hệ thống dữ liệu</b> đến đó thì mới biết mình đã học được gì, để định hình, hình dung — và biết mình cần <b>khởi cầu để được học tiếp</b>.', null, null, '{"so":20,"nhom":"Học & rèn","giai":[],"bam":["congthuc","nguyentac","trong"],"chu_ky":"Hằng tuần"}'::jsonb, 20, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('287c71e4-cf85-511a-896b-201f3951b6e0', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'viettt', 'Viết Trí tuệ', 'Viết là cách <b>giữ lại nguyên vẹn</b> những gì được truyền — và là nền của <b>Luyện viết</b> trong 5 thứ cần luyện.', null, null, '{"so":21,"nhom":"Học & rèn","giai":[],"bam":["nguyentac","congthuc","trietde"],"chu_ky":"Sau mỗi buổi học"}'::jsonb, 21, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('b32b7bcd-d05b-500b-8fb8-3bf61661815e', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'luyen', 'Sống cần luyện', 'Luyện phải <b>công phu</b> và muốn luyện thì phải <b>trì</b>. Luyện tầm — quan sát và nhận diện được thực tế — là <b>quan trọng nhất</b>.', null, null, '{"so":22,"nhom":"Học & rèn","giai":["Hành xử kém"],"bam":["nguyenly","dao","nguyentac","congthuc","trong"],"chu_ky":"Hằng ngày"}'::jsonb, 22, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('7b7bcf26-d481-58e9-bf9a-443f6c0d9485', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'tuduc', 'Tu đức', '<b>Có đức thì mới độ được cho người khác, mới nói có người nghe.</b> Tu đức là để <b>lập đức</b> — mà có đức thì mới giữ được 7 phần.', null, null, '{"so":23,"nhom":"Học & rèn","giai":["Lỗi đạo","Khuyết đức → mất phần","Phúc đức cạn"],"bam":["dao","nguyenly","goc","nguyentac"],"chu_ky":"Suốt đời"}'::jsonb, 23, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('1ebb4c95-65ac-5085-a3c1-7825566c5fb3', 'khuon', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'kethua', 'Kế thừa cho tương lai', 'Chia sẻ Trí tuệ cho con là để <b>hóa giải mầm ân oán trong gia đình</b> — con đến báo ơn hoặc con đến đòi nợ. <b>Con mình thì trực chỉ, con người khác thì định hướng.</b>', null, null, '{"so":24,"nhom":"Truyền lại","giai":["Nợ công, nợ của","Oan gia trái chủ"],"bam":["tamtubi","thautriet","tron","trong"],"chu_ky":"Hằng tuần"}'::jsonb, 24, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('30f7ea17-0e62-5f1d-b3e3-9988b17e1792', 'khuon_khoi', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'gd', 'Gia đình', null, null, null, '{"ung_dung":["<b>Thấu triệt</b> <em>(chỉ cần một lần)</em> — <b>Gia đình</b>: định vị gia đình (phúc đức · nghiệp chướng · hoàn cảnh) · văn hóa · quy định · nguyên tắc. <b>Người trong gia đình</b>: tính cách · thói quen, sở thích · nguyên tắc","<b>Tròn chức năng, vai trò, bổn phận, trách nhiệm với gia đình</b> <em>(hằng ngày)</em>","<b>Tạo nếp nhà</b> <em>(thường xuyên)</em> — chia sẻ Trí tuệ cho mọi người trong nhà · giữ giới giữ hạnh · sắp xếp phòng ăn, phòng ngủ, phòng khách, phòng thờ · sống đúng quy định gia đình về giờ giấc, ăn uống nghỉ ngơi, quần áo trang phục, quan hệ","<b>Tròn Hiếu – Lễ – Nghĩa</b> — hằng ngày: thờ tự chuẩn, kính lễ sáng tối · đại hiếu · trọng · lễ phép. Khi nhà có việc: gia quy · làm chủ các khóa lễ","<b>Kế thừa Trí tuệ cho con cháu</b>"],"them":[],"bam":["kiemsoat","dungdao","nguyentac"]}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('437e1971-77ce-5382-bd08-91b4ff88f5fb', 'khuon_khoi', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'cv', 'Công việc', null, null, null, '{"ung_dung":["<b>Thấu triệt công việc</b> — môi trường · luật · quy định · văn hóa · quy trình · nguyên tắc","<b>Làm công việc đúng mệnh</b>","<b>Hành xử và đối nhân xử thế</b> — <em>người làm chủ</em>: lắng nghe ý tưởng của nhân viên, biết sắp xếp đúng người đúng việc. <em>Nhân viên làm thuê</em>: phát huy đúng chuyên môn, phát huy cái tài của mình","<b>Trân trọng và biết ơn</b>","<b>Tạo phúc, trả nợ ở cơ quan</b> — cho các thần linh · cho các vong linh vất vưởng · cho nhân viên, đồng nghiệp <em>(để không bị phá, bị chướng cản trong công việc)</em>","<b>Tròn chức năng, vai trò, bổn phận, trách nhiệm trong công việc</b> — với việc đã nhận lời thì cần tròn tâm, tròn việc, tròn đạo, tròn nhân duyên để không bị trả nghiệp đời","<b>Kiểm soát</b> <em>(hằng ngày)</em> — cảm xúc · hành động · tài chính"],"them":[],"bam":["nguyenly","thoithe","tron","dungdao","nguyentac","goc","dungluat"]}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('dd277da7-c7c9-5d30-b248-2618181b6a1d', 'khuon_khoi', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'qh', 'Quan hệ', null, null, null, '{"ung_dung":["<b>Thấu triệt con người</b> — tính cách · thói quen, sở thích · nguyên tắc. Có những người ta không thể chơi được; có những người quan hệ theo <b>nguyên tắc 3 lần</b> của Trí tuệ, vượt quá 3 lần thì không chơi nữa","<b>Phân ra từng mối quan hệ rõ ràng</b> — quan hệ gia đình / quan hệ xã hội, và 3 loại: <b>Bất biến</b> (không bao giờ tính toán · sẵn sàng bảo vệ · sẵn sàng hy sinh · luôn giữ đạo · hành xử cao hơn một bậc) · <b>Tâm giao</b> (luôn giữ đạo · chia sẻ được các vấn đề trong cuộc sống) · <b>Xã giao</b> (dĩ hòa vi quý và đúng đạo)","<b>Cần trọng các mối quan hệ</b> để không bị lỗi đạo","<b>Rà soát thường xuyên</b> — cứ <b>3–6 tháng</b> rà soát một lần để định vị lại các mối quan hệ"],"them":[],"bam":["kiemsoat","xetnguoi","nguyentac"]}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('e479ca72-b348-55fc-94aa-33fd7e50f10d', 'khuon_khoi', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'tc', 'Tài chính', null, null, null, '{"ung_dung":["<b>Thấu triệt</b> — tiền sạch / tiền bẩn · thời thế"],"them":["<b>Kiểm soát chi tiêu</b>: chia 5 khoản · tăng cường tiết kiệm · có tiền tiết kiệm thì gửi ngân hàng, mua vàng, mua đô la","<b>Kiểm soát tài chính</b>: dù vay ngoài lãi suất cao hay vay ngân hàng thì đều cần thu gom để trả · làm đúng 5 luật · khi làm việc phải tròn","<b>Kiểm soát hành động</b>: hạn chế cho vay; nếu có người hỏi vay thì có thể cho họ một khoản nhỏ tùy theo thực tế"],"bam":["kiemsoat","nguyentac"]}'::jsonb, 3, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('2508550b-8366-5002-8ae5-b90784535497', 'khuon_khoi', null, 'c549fc85-825c-5631-bfb1-72291c4e5c27', 'xh', 'Xã hội', null, null, null, '{"ung_dung":["<b>Thấu triệt môi trường ngoài xã hội</b> — luật · quy định · văn hóa · nguyên tắc","<b>Đối nhân xử thế</b>","<b>Đối xử bằng nhân tâm với con người và vạn vật</b>","<b>Báo ơn, báo hiếu, trả nợ</b>"],"them":[],"bam":["kiemsoat","xetnguoi","dungdao","hoanhi","xabo","tuyduyen","trietde"]}'::jsonb, 4, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
