insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('510fedfa-fe41-56a4-aaee-969f0c3210ac', 'nhanh', '0ba29fef-f860-5d4d-898a-9f7b6cf0df53', '486cdc6d-3902-5eb6-ae1e-991b35918e15', 'MẢNG 3–5', 'PHÁP · TÂM LINH · THỰC TẾ', 'Ba mảng này <b>chưa xuất hiện thành chương riêng</b> trong bản Cốt dữ liệu Phần 1 — nội dung nằm rải trong các phần khác.', null, 'trong', '{}'::jsonb, 10, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('3b201ddc-ccd0-59cf-b452-8085238462f9', 'nhanh', 'e5e56919-8d7e-560b-9008-f78c42c2ecee', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '6 QUY LUẬT', 'Tạo hóa · Trời Phật · Thời thế · Con người · Vạn vật · Thời gian', 'Sống cần thuận quy luật tự nhiên vì các Ngài định vị tất cả mọi thứ ở cõi Ta Bà bằng <b>Nhân quả – Phúc đức – Nhân duyên</b>.', null, 'qc', '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('2104467c-19df-57f0-adc9-ed4a9f9017d0', 'nhanh', 'bf262abd-aee4-538e-8a75-c4185295c8ae', '486cdc6d-3902-5eb6-ae1e-991b35918e15', 'HIẾU', '3 cấp độ hiếu', 'Với ông bà bố mẹ còn sống, và với gia tiên tiền tổ — mỗi bên có 3 cấp.', null, 'qc', '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('d7f8cc71-133f-51c3-906a-f3312cffb4e5', 'nhanh', 'bf262abd-aee4-538e-8a75-c4185295c8ae', '486cdc6d-3902-5eb6-ae1e-991b35918e15', 'LỄ', 'Lễ phép · Lễ nghi · Nghi thức', 'Làm chủ <b>8 bộ lễ Trí tuệ</b> (36 khóa lễ).', null, 'qc', '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('58045179-c366-5fe9-8f46-c3f275b375fe', 'nhanh', 'bf262abd-aee4-538e-8a75-c4185295c8ae', '486cdc6d-3902-5eb6-ae1e-991b35918e15', 'NGHĨA', 'Trân trọng và biết ơn với con người và vạn vật', 'Muốn có <b>ĐỨC LƯU QUANG</b> lưu truyền mãi thì con cháu phải biết trân trọng và biết ơn, mới không cắt đứt mạch nguồn phúc đức ông bà để lại.', null, 'qc', '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('0558f977-9a91-59c9-b510-86711e120784', 'nhanh', '68010225-cb51-5bc8-b5eb-f04104281194', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '5 GỐC', '5 gốc phải bám khi làm bất kỳ việc gì', '<em>Bản gốc ghi “có 4 ý chính” nhưng liệt kê 5 gốc.</em>', null, 'qc', '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('4e4fb4de-a51e-5064-85dc-6eb4bba112ba', 'nhanh', '68010225-cb51-5bc8-b5eb-f04104281194', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '11 GỐC', 'Gốc của từng vấn đề', 'Bảng này rất đáng thuộc — mọi bất ổn đều truy về đây.', null, 'qc', '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
