insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('bf1fbb7a-dd8f-59df-a0bc-d7791001e676', 'nhanh', '4cbb4b48-234c-5a64-b84b-ce8ce700e431', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '§1', '6 nguyên nhân bất ổn', '', null, 'qc', '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('0b83defc-5603-56e2-b59e-076130f36a98', 'nhanh', '4cbb4b48-234c-5a64-b84b-ce8ce700e431', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '§2', '7 phương pháp hóa giải bất ổn', '', null, 'ud', '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('1e3c7fb6-f469-5cfb-bfc9-2c6a49515ae5', 'nhanh', '4cbb4b48-234c-5a64-b84b-ce8ce700e431', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '§3', 'Đời – Đạo – Lợi tư — kiềng 3 chân', '<b>Lợi tư là phần ta được hưởng NẾU có Phúc và Đức. Muốn có phúc đức thì cần có Đời và Đạo.</b>', null, 'qc', '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('57a74504-573c-5283-97bd-26ae4982b2d6', 'nhanh', '4cbb4b48-234c-5a64-b84b-ce8ce700e431', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '§4', 'Cõi Ta Bà', '', null, 'qc', '{}'::jsonb, 3, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('e9394ebc-8787-5263-b975-c66693018c9b', 'nhanh', '4cbb4b48-234c-5a64-b84b-ce8ce700e431', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '§5', 'Mệnh và Sứ mệnh', '<b>Mệnh</b> = cái mình có. <b>Sứ mệnh</b> = cái mình cho đi.', null, 'qc', '{}'::jsonb, 4, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('26df379d-20b0-5ee4-bd3f-c0ebfb9c23ef', 'nhanh', '4cbb4b48-234c-5a64-b84b-ce8ce700e431', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '§6', '4 dạng Tâm', 'Biết 4 dạng tâm để ① <b>kiểm soát nội tâm</b> ② <b>xét người</b>.', null, 'qc', '{}'::jsonb, 5, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('20cfa3ef-c368-53b2-9f03-d4cae164a032', 'nhanh', '4cbb4b48-234c-5a64-b84b-ce8ce700e431', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '§7', 'Gốc Phật', 'Đức tin Gốc Phật tại Việt Nam · dấu ấn cây đèn dầu · Ngài Thích Ca hạ thế · pháp bị tổn.', null, 'qc', '{}'::jsonb, 6, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('3b71410c-b3e4-53fe-9887-ae3539a395f5', 'nhanh', '4cbb4b48-234c-5a64-b84b-ce8ce700e431', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '§8', 'Đích của hành sứ mệnh', '', null, 'qc', '{}'::jsonb, 7, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('5a60858f-40d8-5c28-9a3b-fab2cfe8e55b', 'nhanh', '4cbb4b48-234c-5a64-b84b-ce8ce700e431', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '§9', '10 liệu pháp y thuật', '5 liệu pháp đầu là khoa học/y học, 5 liệu pháp sau là tâm linh — đúng với <em>Trí tuệ là Thực tế – Khoa học – Tâm linh</em>.', null, 'qc', '{}'::jsonb, 8, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('8c20bbad-b67c-507b-a8b2-5e653ac96ca1', 'nhanh', '4cbb4b48-234c-5a64-b84b-ce8ce700e431', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '§10', '6 nấc căn cơ cốt mệnh', 'Gắn thẳng khả năng dành thời gian cho Đời và Đạo với căn cơ cốt mệnh.', null, 'qchieu', '{}'::jsonb, 9, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('ab3fae0a-414c-510c-9fe3-cf29f3d0683d', 'nhanh', '4cbb4b48-234c-5a64-b84b-ce8ce700e431', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '§11', 'Hành xử và Đối nhân xử thế', '<b>Hành xử</b> = chủ động trước. <b>Đối nhân xử thế</b> = khi người khác chủ động trước hoặc việc đến với mình.', null, 'qc', '{}'::jsonb, 10, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('1e400903-22ab-5793-a688-08052aec7660', 'nhanh', '4cbb4b48-234c-5a64-b84b-ce8ce700e431', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '§12', 'Nới rộng hiểu biết', '<b>“Hiểu biết đến đâu thì hành xử đến đó.”</b> Không nới rộng thì luôn hành xử bằng hiểu biết hạn hẹp, khiến người khác khó chịu, để lại hệ quả.', null, 'qc', '{}'::jsonb, 11, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('45f1ffa2-dd5c-5c7c-bbd9-f7393f19ad61', 'nhanh', '4cbb4b48-234c-5a64-b84b-ce8ce700e431', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '§13', 'Cốt Phật, cốt Tiên, cốt Phàm', '', null, 'qc', '{}'::jsonb, 12, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('0a7294ae-9de3-5fb0-9964-364935e63c19', 'nhanh', '4cbb4b48-234c-5a64-b84b-ce8ce700e431', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '§14', 'Đức tin vào chính mình', 'Có đức tin vào <b>Cha Mẹ và các Ngài · Trí tuệ · bản thân</b> thì mới dừng lại những việc làm sai để xoay chuyển.', null, 'qc', '{}'::jsonb, 13, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('b4eb7f7a-01ec-5e73-a9d5-dccaf199b21b', 'nhanh', '4cbb4b48-234c-5a64-b84b-ce8ce700e431', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '§15', '5 cặp câu từ dễ nhầm', 'Phân biệt để dùng cho đúng.', null, 'qc', '{}'::jsonb, 14, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('8399665d-496c-5889-ae47-c80fa1fcd9f4', 'nhanh', '4cbb4b48-234c-5a64-b84b-ce8ce700e431', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '§16', 'Tròn chức năng, vai trò, bổn phận, trách nhiệm', 'Làm bất kỳ việc gì cũng tròn cả 4 để <b>không bị nợ và có được Phúc Đức</b>.', null, 'qc', '{}'::jsonb, 15, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('1fba5d16-f8f6-5541-a111-0727d1d2155a', 'nhanh', '4cbb4b48-234c-5a64-b84b-ce8ce700e431', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '§17', 'Nhận diện cảnh — 3 dạng cảnh đổ về', 'Khi có việc xấu xảy ra, đọc dấu hiệu để biết mình đang ở dạng cảnh nào.', null, 'qc', '{}'::jsonb, 16, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('e6e7bb23-58ae-5112-ad3f-cc30cdcc681d', 'nhanh', '4cbb4b48-234c-5a64-b84b-ce8ce700e431', '486cdc6d-3902-5eb6-ae1e-991b35918e15', '§18', 'Công thức đối cảnh và giải cảnh', '<b>Đối cảnh</b> = ta chủ động lập kế hoạch → cho ra <b>pháp đối trị</b>, mà pháp đối trị chính là PHỐI HỢP. <b>Giải cảnh</b> = cảnh đổ về, ta phải giải → cho ra <b>pháp hóa giải</b>, nằm ở “Đích sử dụng Trí tuệ”.', null, 'qc', '{}'::jsonb, 17, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
