insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('012dceda-617f-5c84-aed1-5bca4c5cb9ed', 'tu', '983aed89-7efc-543a-8412-a4a1d06f2b16', '0b735c6c-4cf2-5440-9782-51670ac50250', 'khuon', 'Khuôn', 'Bộ hành động chuẩn cho một lĩnh vực. <b>Khuôn bên trong</b> = 7 khối. <b>Khuôn bên ngoài</b> = nói, làm, hành xử, đối nhân xử thế.', null, null, '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('426e9d08-0cc8-55fe-84ef-11b6f6656962', 'tu', '983aed89-7efc-543a-8412-a4a1d06f2b16', '0b735c6c-4cf2-5440-9782-51670ac50250', 'phap', 'Pháp', 'Cách xử lý. 3 pháp: <b>đối trị · hóa giải · xoay chuyển</b>.', null, null, '{}'::jsonb, 3, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('93c0eb9d-4aeb-5017-a160-a8078c73a14f', 'tu', '983aed89-7efc-543a-8412-a4a1d06f2b16', '0b735c6c-4cf2-5440-9782-51670ac50250', 'y-phap', 'Ý pháp', 'Một đơn vị kiến thức dùng để <b>nhận diện nhanh</b> vấn đề rồi đưa pháp vào — 18 ý pháp trong Phần 6.', null, null, '{}'::jsonb, 4, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('4781ea4d-1460-5f3f-ba0b-55d4228b49a1', 'tu', '983aed89-7efc-543a-8412-a4a1d06f2b16', '0b735c6c-4cf2-5440-9782-51670ac50250', 'the-phap', 'Thế pháp', 'Cách thức chuẩn hóa để mọi người <b>hiểu giống nhau, hành động giống nhau</b> — 10 thế pháp.', null, null, '{}'::jsonb, 5, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('dbe409bc-14e6-5eaf-8d6a-db72a1ccfd0d', 'tu', '983aed89-7efc-543a-8412-a4a1d06f2b16', '0b735c6c-4cf2-5440-9782-51670ac50250', 'truc-chi', 'Trực chỉ', 'Trí tuệ chỉ <b>thẳng, cụ thể</b> phải làm gì → <b>y hành theo</b>.', null, null, '{}'::jsonb, 6, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('9c98fe40-47dc-52dc-ae75-c513ea0eb347', 'tu', '983aed89-7efc-543a-8412-a4a1d06f2b16', '0b735c6c-4cf2-5440-9782-51670ac50250', 'dinh-huong', 'Định hướng', 'Trí tuệ chỉ <b>hướng</b>, còn cách làm cụ thể thì mình phải chủ động nới rộng hiểu biết. <em>Ví dụ: khuôn gia đình không có mục “xây nhà, sửa nhà” → phải tự tìm hiểu về thiết kế, vật liệu, nội thất, thợ, giá cả, thủ tục.</em>', null, null, '{}'::jsonb, 7, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('35d3cc5d-f284-5f30-9b62-2c1fd1880489', 'tu', 'aa60265d-d9c9-5f28-803c-09fd8928bb87', '0b735c6c-4cf2-5440-9782-51670ac50250', 'khai-thac', 'Khai thác', 'Đọc dữ liệu và hỏi: <b>ý này chỉ cho ta biết gì và cần làm gì?</b>', null, null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('147b411c-4e4a-58c9-9c53-50bd9eaefc47', 'tu', 'aa60265d-d9c9-5f28-803c-09fd8928bb87', '0b735c6c-4cf2-5440-9782-51670ac50250', 'quy-chieu', 'Quy chiếu', 'Soi ra thực tế / soi vào bản thân để đối chiếu với quy chuẩn. 2 dạng, 4 loại: hình ảnh · chứng thực · hiện tượng · bản thân.', null, null, '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('8f394085-2b69-5514-b106-b83b7cb8058f', 'tu', 'aa60265d-d9c9-5f28-803c-09fd8928bb87', '0b735c6c-4cf2-5440-9782-51670ac50250', 'bam', 'Bám', 'Giữ mình trong hành lang Trí tuệ khi hành động — <b>14 ý bám</b>.', null, null, '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
