insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('fd6a3dcc-1067-5f80-91a1-71297a70d507', 'tu', 'aa60265d-d9c9-5f28-803c-09fd8928bb87', '0b735c6c-4cf2-5440-9782-51670ac50250', 'ket-noi', 'Kết nối', 'Ghép các ý được mở ra ở nhiều lần / nhiều ý tương đồng / nhiều ý trong lúc khai thác.', null, null, '{}'::jsonb, 4, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
