insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('c82e6fbe-8384-56d5-a626-e8e0fcf3d8f0', 'tu', 'aa60265d-d9c9-5f28-803c-09fd8928bb87', '0b735c6c-4cf2-5440-9782-51670ac50250', 'reset', 'Reset', 'Quay lại guồng khi bị cuốn hoặc mất phương hướng. Cách: ngồi viết lại <em>đã học được gì · kế hoạch là gì · đã triển khai được gì · kết quả đạt gì</em>.', null, null, '{}'::jsonb, 7, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
