insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('9e7b3283-5a59-5061-bf69-652f1dd85b72', 'tu', '4f356e7a-882f-5cd4-9ba4-c269f17e58c6', '0b735c6c-4cf2-5440-9782-51670ac50250', 'goc-do-tac-dong-chinh', 'Góc độ tác động chính', 'Yếu tố <b>chính</b> gây ra một bất ổn cụ thể — tìm ra nó thì mới đưa pháp đúng được.', null, null, '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('86733950-45ef-569e-aca4-6517cf7a184d', 'tu', '4f356e7a-882f-5cd4-9ba4-c269f17e58c6', '0b735c6c-4cf2-5440-9782-51670ac50250', 'oan-gia-trai-chu', 'Oan gia trái chủ', 'Người hoặc vong linh có ân oán với mình từ tiền kiếp, nay đến đòi nợ.', null, null, '{}'::jsonb, 3, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
