insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('a3bb11fb-94cf-52bd-96db-d970706a9510', 'tu', '4f356e7a-882f-5cd4-9ba4-c269f17e58c6', '0b735c6c-4cf2-5440-9782-51670ac50250', 'tra-nghiep-giai-nghiep-dung-nghiep', 'Trả nghiệp / Giải nghiệp / Dừng nghiệp', '<b>Trả nghiệp</b> = chủ động trả trước cho nghiệp đã tạo nhưng chưa đổ về. <b>Giải nghiệp</b> = xử lý khi nghiệp đã đổ về. <b>Dừng nghiệp</b> = không tạo nghiệp mới, bằng cách đưa khuôn Trí tuệ vào cuộc sống.', null, null, '{}'::jsonb, 5, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
