insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('96e84aba-84aa-5fee-b435-c63b19e0c18c', 'tu', '4f356e7a-882f-5cd4-9ba4-c269f17e58c6', '0b735c6c-4cf2-5440-9782-51670ac50250', 'lo-phi-cho-gia-tien', 'Lộ phí cho gia tiên', 'Tiền làm hằng tháng để gia tiên có phúc bay qua các vùng đất, cầu phà do các thần cai quản — <b>thay cho vàng mã</b>.', null, null, '{}'::jsonb, 8, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
