insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('c57a47f0-0940-5993-a3ca-e0d013ffdbed', 'y', '1d6b477a-a5f9-54d1-a78f-9547a11d7a9b', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Thời này không phải thời làm giàu, mà là thời cần rốt ráo Tạo phúc – Trả nghiệp – Tu', null, 'Thời này <b>không phải thời làm giàu</b>, mà là thời cần rốt ráo <b>Tạo phúc – Trả nghiệp – Tu</b>', null, '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('b288c48a-3692-517e-867a-7822f6df5927', 'y', 'facd4101-c55e-526a-a73b-1ef7149b4465', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Qua ánh mắt — mắt thiện = tâm thiện · mắt trong sáng có thần = tâm sáng · tâm loạn thì mắt loạn · người trung trực hay nhìn thẳng · mắt đỏ, hay nhìn trộm = có vong · mắt đảo điên, lấm lét = gian xảo …', null, '<b>Qua ánh mắt</b> — mắt thiện = tâm thiện · mắt trong sáng có thần = tâm sáng · tâm loạn thì mắt loạn · người trung trực hay nhìn thẳng · mắt đỏ, hay nhìn trộm = có vong · mắt đảo điên, lấm lét = gian xảo · mắt không biểu cảm = đang dò xét · người tự ti hay nhìn trần nhà hoặc nhìn đất, nói nhỏ', null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('fe051e4e-d7d4-52d8-bed7-a0af7d59f445', 'y', 'facd4101-c55e-526a-a73b-1ef7149b4465', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Qua lời nói — nói thói thường: không trả lời trực diện, lái sang chuyện khác, chỉ dạ vâng cho qua. Nói Trí tuệ: đủ câu – đủ ý – đủ nghĩa – đủ từ, đúng nguyên lý, đúng đạo, đúng nguyên tắc. Mẹo: cho h…', null, '<b>Qua lời nói</b> — <em>nói thói thường</em>: không trả lời trực diện, lái sang chuyện khác, chỉ dạ vâng cho qua. <em>Nói Trí tuệ</em>: đủ câu – đủ ý – đủ nghĩa – đủ từ, đúng nguyên lý, đúng đạo, đúng nguyên tắc. <b>Mẹo: cho họ hỏi mình một câu để biết tâm và tầm của họ</b>', null, '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('73223414-1c78-5274-8d2a-0b8bf7dd7612', 'y', 'facd4101-c55e-526a-a73b-1ef7149b4465', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Qua hành động — “Bậc quân cư xử bình dị để đãi mệnh / Kẻ tiểu nhân hành động nguy hiểm để cầu may”. Nhìn cách họ hành xử với những người khác nhau xem có chuẩn đạo như nhau không · thử người bằng hàn…', null, '<b>Qua hành động</b> — <em>“Bậc quân cư xử bình dị để đãi mệnh / Kẻ tiểu nhân hành động nguy hiểm để cầu may”</em>. Nhìn cách họ hành xử với <em>những người khác nhau</em> xem có chuẩn đạo như nhau không · thử người bằng hành động', null, '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('bd552694-a1f3-56db-be74-ad4ebd073034', 'y', 'facd4101-c55e-526a-a73b-1ef7149b4465', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Qua thần khí — mắt sáng, mắt định, lời nói có hồn khí = thần khí tốt · mắt lờ đờ, uể oải = không sinh khí · da xanh tái = năng lượng kém · da sạm = có vấn đề sức khỏe, vận đi xuống', null, '<b>Qua thần khí</b> — mắt sáng, mắt định, lời nói có hồn khí = thần khí tốt · mắt lờ đờ, uể oải = không sinh khí · da xanh tái = năng lượng kém · da sạm = có vấn đề sức khỏe, vận đi xuống', null, '{}'::jsonb, 3, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('23b9b28f-c2a9-52a6-8f32-675af32b4f82', 'y', 'facd4101-c55e-526a-a73b-1ef7149b4465', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, '7 ý giải thích vì sao con người phức tạp: 4 dạng tâm · 5 dạng tái sinh và 2 nhóm xuống trần hành đạo · 4 dạng tập khí · thực tế con người hiện nay · cốt Phật–cốt Tiên–cốt Phàm · 6 nấc căn cơ cốt mệnh…', null, '<b>7 ý giải thích vì sao con người phức tạp</b>: 4 dạng tâm · 5 dạng tái sinh và 2 nhóm xuống trần hành đạo · 4 dạng tập khí · thực tế con người hiện nay · cốt Phật–cốt Tiên–cốt Phàm · 6 nấc căn cơ cốt mệnh · nhóm trí thức–thói thường–trí tuệ', null, '{}'::jsonb, 4, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('5ee45428-2f33-5181-825d-d26c4befa1ce', 'y', '7301b5f6-23de-5a28-9fb0-3e5b24e05903', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Sức khỏe — tư tưởng tinh thần phải thông · trọng thân: chọn việc đáng mới làm, dinh dưỡng cân bằng, vận động sinh hoạt hợp lý', null, '<b>Sức khỏe</b> — tư tưởng tinh thần phải thông · <b>trọng thân</b>: chọn việc đáng mới làm, dinh dưỡng cân bằng, vận động sinh hoạt hợp lý', null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
