insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('caec3d2b-9359-5bf6-aeac-41579dc8a0d4', 'y', 'ba5491b8-481d-586a-ac2a-a5280e98f68e', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Rõ ràng — không mập mờ. Ai nhận việc gì cũng phải hỏi rõ có chắc chắn không; mình nhận việc gì phải nói rõ làm được bao nhiêu % → để lại ấn tượng', null, '<b>Rõ ràng</b> — không mập mờ. Ai nhận việc gì cũng phải hỏi rõ có chắc chắn không; mình nhận việc gì phải nói rõ làm được bao nhiêu % → <em>để lại ấn tượng</em>', null, '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('0ca74766-407a-5ae9-9d94-33834c199f36', 'y', 'ba5491b8-481d-586a-ac2a-a5280e98f68e', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Có trước có sau — quay lại gốc ban đầu, ai giúp mình từ đầu thì trân trọng biết ơn; trong công việc phải báo cáo trước sau → được ghi nhận', null, '<b>Có trước có sau</b> — quay lại gốc ban đầu, ai giúp mình từ đầu thì trân trọng biết ơn; trong công việc phải báo cáo trước sau → <em>được ghi nhận</em>', null, '{}'::jsonb, 3, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('98bf7b88-f89a-5e65-a350-18ea7627e3c1', 'y', 'ba5491b8-481d-586a-ac2a-a5280e98f68e', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Tinh tế uyển chuyển — tinh tế nhận diện thực tế rồi uyển chuyển theo thời điểm, căn cơ, hoàn cảnh. Nhưng vẫn bám đích, vẫn dùng pháp Trí tuệ, không chuyển sang thói thường. Chỉ uyển chuyển khi bất kh…', null, '<b>Tinh tế uyển chuyển</b> — tinh tế nhận diện thực tế rồi uyển chuyển theo thời điểm, căn cơ, hoàn cảnh. Nhưng <b>vẫn bám đích</b>, vẫn dùng pháp Trí tuệ, không chuyển sang thói thường. Chỉ uyển chuyển khi bất khả kháng', null, '{}'::jsonb, 4, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
