insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('8d53556e-5ce2-59e7-92b1-f4e938305f2d', 'y', '0b83defc-5603-56e2-b59e-076130f36a98', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Sửa thân, tâm, khẩu, ý — tu sửa thân: không đến nơi uế tạp, không ăn uống vô độ, không lao tâm khổ tứ, không đam mê sắc dục. Tu sửa tâm: không tà tâm, không mưu mô, không toan tính. Tu sửa khẩu: nói …', null, '<b>Sửa thân, tâm, khẩu, ý</b> — <em>tu sửa thân</em>: không đến nơi uế tạp, không ăn uống vô độ, không lao tâm khổ tứ, không đam mê sắc dục. <em>Tu sửa tâm</em>: không tà tâm, không mưu mô, không toan tính. <em>Tu sửa khẩu</em>: nói rõ ràng chuẩn mực đúng lúc đúng chỗ, đủ câu đủ ý đủ từ, trước sau như một, không trêu đùa, không hứa việc chưa chắc chắn, không khuyên người khác, không kiếm chuyện làm quà. <em>Tu sửa ý</em>: không suy tưởng, suy diễn, suy tính, suy đoán — <b>nghe đâu biết đấy, nghe đâu bỏ đấy; khi nào làm thì dùng Trí tuệ</b>', null, '{}'::jsonb, 6, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('a0740c6f-1716-5ef1-919d-8c5d733845d2', 'y', '1e3c7fb6-f469-5cfb-bfc9-2c6a49515ae5', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'LỢI TƯ (ứng với trả nghiệp) — bản thân · gia đình · quan hệ · công việc · tài chính', null, '<b>LỢI TƯ</b> (ứng với <em>trả nghiệp</em>) — bản thân · gia đình · quan hệ · công việc · tài chính', null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
