insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('2d6ca074-e766-5b3e-a2dc-2b68d3b72727', 'y', '1e3c7fb6-f469-5cfb-bfc9-2c6a49515ae5', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'ĐẠO (ứng với tu tiếp) — học Trí tuệ (được học, tự học, đàm đạo) và tu đức (đúng đạo, tròn đạo, cầu đạo, hành đạo, tu đạo)', null, '<b>ĐẠO</b> (ứng với <em>tu tiếp</em>) — học Trí tuệ (được học, tự học, đàm đạo) và tu đức (đúng đạo, tròn đạo, cầu đạo, hành đạo, tu đạo)', null, '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('ea65c2a0-9804-5c07-ac7b-1160add78d54', 'y', '1e3c7fb6-f469-5cfb-bfc9-2c6a49515ae5', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, '“Trời sinh ra Đạo Đời bỏ phí / Xuống cõi trần chỉ nghĩ lợi tư / Chẳng hiểu gì bổn đạo nhân từ / Chẳng hiểu gì thiên thư Trời Phật”', null, '<em>“Trời sinh ra Đạo Đời bỏ phí / Xuống cõi trần chỉ nghĩ lợi tư / Chẳng hiểu gì bổn đạo nhân từ / Chẳng hiểu gì thiên thư Trời Phật”</em>', null, '{}'::jsonb, 3, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('e5044550-e650-5480-9025-71db4920db51', 'y', '57a74504-573c-5283-97bd-26ae4982b2d6', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, '5 dạng tái sinh: quỷ · súc sinh · người · atula · cõi trời → đầu thai làm người', null, '<b>5 dạng tái sinh</b>: quỷ · súc sinh · người · atula · cõi trời → đầu thai làm người', null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('e3ebec57-7158-5b30-b38c-ea2a93ffb178', 'y', '57a74504-573c-5283-97bd-26ae4982b2d6', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, '2 nhóm xuống trần hành đạo: nhóm có mệnh Bồ Tát · nhóm có mệnh cửa Thiên', null, '<b>2 nhóm xuống trần hành đạo</b>: nhóm có mệnh Bồ Tát · nhóm có mệnh cửa Thiên', null, '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('696f7c91-5299-5cd2-889a-5a7f8d622f2d', 'y', '57a74504-573c-5283-97bd-26ae4982b2d6', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, '3 lần Mẹ Phật Mẫu Địa hạ thế: ① tách Trời Đất, định vị âm dương cho 4 loài vào sinh sống ② hóa thành Mẫu Âu Cơ sinh bọc trứng Tiên Rồng để loài người có cốt Phật cốt Tiên ③ vào thời đáy của đại Mạt, …', null, '<b>3 lần Mẹ Phật Mẫu Địa hạ thế</b>: ① tách Trời Đất, định vị âm dương cho 4 loài vào sinh sống ② hóa thành Mẫu Âu Cơ sinh bọc trứng Tiên Rồng để loài người có cốt Phật cốt Tiên ③ vào thời đáy của đại Mạt, xin Vua Cha chuyển diệt vong thành sàng lọc, ban Trí tuệ xuống trần', null, '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('5c70c2f5-dbfd-5ec8-a4d7-18393bf10cd1', 'y', '57a74504-573c-5283-97bd-26ae4982b2d6', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, '5 nền văn minh: săn bắn hái lượm · lúa nước · công nghiệp · công nghệ thông tin · khoa học, vũ trụ và tâm linh — con người đang ở cuối nền văn minh 4, bắt đầu chuyển sang 5', null, '<b>5 nền văn minh</b>: săn bắn hái lượm · lúa nước · công nghiệp · công nghệ thông tin · khoa học, vũ trụ và tâm linh — <em>con người đang ở cuối nền văn minh 4, bắt đầu chuyển sang 5</em>', null, '{}'::jsonb, 3, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('ac53beb2-100f-57fc-b6fb-c6412b1401b4', 'y', 'e9394ebc-8787-5263-b975-c66693018c9b', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Căn cơ — mỗi người có một căn cơ ứng với một ngành nghề, công việc', null, '<b>Căn cơ</b> — mỗi người có một căn cơ ứng với một ngành nghề, công việc', null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('67eca256-d8e5-5803-b943-43814471d771', 'y', 'e9394ebc-8787-5263-b975-c66693018c9b', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Cốt mệnh — bộ khung: khung chắc → mệnh tốt; khung yếu → mệnh yếu', null, '<b>Cốt mệnh</b> — bộ khung: khung chắc → mệnh tốt; khung yếu → mệnh yếu', null, '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('a9671001-1e98-54e8-9b2a-2e6c944f50c6', 'y', 'e9394ebc-8787-5263-b975-c66693018c9b', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Mệnh người làm chủ — bám được chuyên môn · nhiều ý tưởng sáng kiến · biết quản lý, kiểm soát, suy xét đa chiều · có tầm nhìn, khát vọng, ý chí · có tâm đức · giữ được đạo', null, '<b>Mệnh người làm chủ</b> — bám được chuyên môn · nhiều ý tưởng sáng kiến · biết quản lý, kiểm soát, suy xét đa chiều · có tầm nhìn, khát vọng, ý chí · có tâm đức · giữ được đạo', null, '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('2c63a10b-099a-583c-bd69-9d6b9f2afcd8', 'y', 'e9394ebc-8787-5263-b975-c66693018c9b', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Mệnh người làm thuê — không ý tưởng, không sáng kiến · giao việc gì làm việc đó · không hoạt bát', null, '<b>Mệnh người làm thuê</b> — không ý tưởng, không sáng kiến · giao việc gì làm việc đó · không hoạt bát', null, '{}'::jsonb, 3, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('779f022e-923a-5f79-99ea-ca9cc1474111', 'y', 'e9394ebc-8787-5263-b975-c66693018c9b', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Tài riêng — tài được ban ngoài công việc; có người tài ẩn, có người tài lộ', null, '<b>Tài riêng</b> — tài được ban ngoài công việc; có người tài ẩn, có người tài lộ', null, '{}'::jsonb, 4, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('cd0f8dc1-9114-5888-8862-526a857f373e', 'y', 'e9394ebc-8787-5263-b975-c66693018c9b', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Sứ mệnh = cống hiến vô danh vô lợi. Mỗi thời kỳ một sứ mệnh khác nhau; sứ mệnh đáng nhất thời này là Lan tỏa Trí tuệ', null, '<b>Sứ mệnh</b> = cống hiến vô danh vô lợi. Mỗi thời kỳ một sứ mệnh khác nhau; <b>sứ mệnh đáng nhất thời này là Lan tỏa Trí tuệ</b>', null, '{}'::jsonb, 5, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('76c6fcbc-3074-518e-8e91-c61dfbfada56', 'y', '26df379d-20b0-5ee4-bd3f-c0ebfb9c23ef', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Tâm thú — việc gì không hài lòng thì phản ứng ngay: sân hận · tiêu cực · thù địch · độc ác', null, '<b>Tâm thú</b> — việc gì không hài lòng thì phản ứng ngay: sân hận · tiêu cực · thù địch · độc ác', null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('f48964b4-3ed8-5670-8429-d2d253b39bcf', 'y', '26df379d-20b0-5ee4-bd3f-c0ebfb9c23ef', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Tâm ma — si mê · mê mờ · mê muội. Người thiên về cảm xúc rất dễ bị tâm ma dẫn dắt', null, '<b>Tâm ma</b> — si mê · mê mờ · mê muội. <em>Người thiên về cảm xúc rất dễ bị tâm ma dẫn dắt</em>', null, '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('fd93b026-6194-508f-b547-14998fce1803', 'y', '26df379d-20b0-5ee4-bd3f-c0ebfb9c23ef', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Tâm người — tham lam · tính toán · bon chen · ganh ghét · đố kỵ · hẹp hòi ích kỷ · khéo léo · che đậy · nịnh bợ → vòng luẩn quẩn Tham – Sân – Si → Khổ đau', null, '<b>Tâm người</b> — tham lam · tính toán · bon chen · ganh ghét · đố kỵ · hẹp hòi ích kỷ · khéo léo · che đậy · nịnh bợ → vòng luẩn quẩn <em>Tham – Sân – Si → Khổ đau</em>', null, '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('8cbb6c55-ded0-5a80-bff3-7b61e41f028b', 'y', '26df379d-20b0-5ee4-bd3f-c0ebfb9c23ef', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Tâm Phật — Đại từ (hiền từ, lành như đất) · Đại bi (cứu khổ cứu nạn, yêu thương vô điều kiện) · Đại hỉ (hoan hỉ) · Đại xả (xả bỏ 3 tâm kia)', null, '<b>Tâm Phật</b> — <b>Đại từ</b> (hiền từ, lành như đất) · <b>Đại bi</b> (cứu khổ cứu nạn, yêu thương vô điều kiện) · <b>Đại hỉ</b> (hoan hỉ) · <b>Đại xả</b> (xả bỏ 3 tâm kia)', null, '{}'::jsonb, 3, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('dfd5f069-afa5-5b00-b4b6-d88601923f6f', 'y', '26df379d-20b0-5ee4-bd3f-c0ebfb9c23ef', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Cách luyện tâm Phật: chậm lại để suy xét và quy chiếu vào Trí tuệ rồi mới trả lời hoặc hành động · học theo tấm gương các Ngài · ấn định tâm Phật 24/24 tiếng', null, '<b>Cách luyện tâm Phật</b>: chậm lại để suy xét và quy chiếu vào Trí tuệ rồi mới trả lời hoặc hành động · học theo tấm gương các Ngài · <b>ấn định tâm Phật 24/24 tiếng</b>', null, '{}'::jsonb, 4, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('0878ba8a-8ced-54b9-803a-ddbd04c00311', 'y', '20cfa3ef-c368-53b2-9f03-d4cae164a032', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Cây đèn dầu — của vị Phật đắc đạo đầu tiên ở Việt Nam, niên hiệu Nhiên Đăng Cổ Phật. Ngài để lại ngọn đăng; thờ ngọn đăng là thờ ánh sáng quang minh của Phật và được khai tuệ. Con người rước ngọn đăn…', null, '<b>Cây đèn dầu</b> — của vị Phật đắc đạo đầu tiên ở Việt Nam, niên hiệu <b>Nhiên Đăng Cổ Phật</b>. Ngài để lại <em>ngọn đăng</em>; thờ ngọn đăng là thờ ánh sáng quang minh của Phật và được khai tuệ. Con người rước ngọn đăng vào đèn dầu để giữ, và thờ cả ngày cả đêm <b>để xóa màn u minh, tăm tối</b>', null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('c6f68daa-5968-511e-9eb5-a94005c1b314', 'y', '20cfa3ef-c368-53b2-9f03-d4cae164a032', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Không dùng vàng mã — vàng mã đốt đi là hết; đốt quần áo giả là lừa gia tiên; chỉ có các Ngài mới biết gia tiên đang ở cõi nào', null, '<b>Không dùng vàng mã</b> — vàng mã đốt đi là hết; đốt quần áo giả là lừa gia tiên; chỉ có các Ngài mới biết gia tiên đang ở cõi nào', null, '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('cf6a045c-389c-50d3-9b3a-f29fa023d911', 'y', '20cfa3ef-c368-53b2-9f03-d4cae164a032', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Không cúng mặn — vạn vật đều có linh; sát sinh một con gà thì mình mắc tội và gia tiên bị đọa. Chỉ dùng thanh bông hoa quả, xôi chè; không có điều kiện thì chén nước, thẻ hương các Ngài cũng chứng — …', null, '<b>Không cúng mặn</b> — vạn vật đều có linh; sát sinh một con gà thì mình mắc tội và gia tiên bị đọa. Chỉ dùng thanh bông hoa quả, xôi chè; không có điều kiện thì chén nước, thẻ hương các Ngài cũng chứng — <b>các Ngài chứng tâm không chứng lễ</b>', null, '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('ca926431-eb9a-56bd-aa21-1fefbf5d0478', 'y', '20cfa3ef-c368-53b2-9f03-d4cae164a032', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Không cúng hình nhân thế mạng — cô hồn nhập vào hình nhân và chết thay; đến ngày cô hồn muốn luân hồi sẽ bắt người nhà chết thay', null, '<b>Không cúng hình nhân thế mạng</b> — cô hồn nhập vào hình nhân và chết thay; đến ngày cô hồn muốn luân hồi sẽ bắt người nhà chết thay', null, '{}'::jsonb, 3, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('322de0c8-a8d7-577a-822d-81df2b257db5', 'y', '20cfa3ef-c368-53b2-9f03-d4cae164a032', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Bát hương phải một bên rồng, một bên phượng — để thờ cả Cha và Mẹ; thờ hai bên rồng là mới thờ một vế của Cha', null, '<b>Bát hương phải một bên rồng, một bên phượng</b> — để thờ cả Cha và Mẹ; thờ hai bên rồng là mới thờ một vế của Cha', null, '{}'::jsonb, 4, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('75891cd6-797c-5bab-a7b2-246d29d9b129', 'y', '3b71410c-b3e4-53fe-9887-ae3539a395f5', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Báo Tứ đại trọng ơn: ơn Trời Phật · ơn Thầy Tổ đã đưa đạo xuống đời · ơn Hồn thiêng sông núi, hồn thiêng dân tộc · ơn gia tiên tiền tổ, ông bà bố mẹ', null, 'Báo <b>Tứ đại trọng ơn</b>: ơn Trời Phật · ơn Thầy Tổ đã đưa đạo xuống đời · ơn Hồn thiêng sông núi, hồn thiêng dân tộc · ơn gia tiên tiền tổ, ông bà bố mẹ', null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('d29c1049-fb15-51c1-9d74-18cafd242fd6', 'y', '3b71410c-b3e4-53fe-9887-ae3539a395f5', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Hóa giải ân oán · Tạo phúc trả nợ báo ơn báo hiếu · Cống hiến vô danh vô lợi · Giữ chân mệnh · Luyện Trí tuệ', null, 'Hóa giải ân oán · Tạo phúc trả nợ báo ơn báo hiếu · Cống hiến vô danh vô lợi · Giữ chân mệnh · Luyện Trí tuệ', null, '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('da9cbda8-9fee-5c6d-a400-ad50c13644e4', 'y', '5a60858f-40d8-5c28-9a3b-fab2cfe8e55b', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Thân bệnh — do ngủ nghỉ không hợp lý, chế độ ăn uống, độc tố, rối loạn chuyển hóa, kinh lạc bị bó. Chữa: bệnh viện và bác sỹ · tâm lý liệu pháp · điều chỉnh ăn uống sinh hoạt · đả thông kinh lạc · hồ…', null, '<b>Thân bệnh</b> — do ngủ nghỉ không hợp lý, chế độ ăn uống, độc tố, rối loạn chuyển hóa, kinh lạc bị bó. Chữa: bệnh viện và bác sỹ · tâm lý liệu pháp · điều chỉnh ăn uống sinh hoạt · đả thông kinh lạc · hồi phục cơ thể', null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('36d31020-6090-5c9a-aa02-63a25da85b57', 'y', '5a60858f-40d8-5c28-9a3b-fab2cfe8e55b', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Tâm bệnh — do cuộc sống bất ổn, không có Trí tuệ để giải nên lo lắng nhiều → tâm loạn, u uất, bó tâm → ăn không hấp thụ được → suy nhược. Chữa: “Muốn chữa bệnh ở thân thì tập cho tâm lành trước đã” —…', null, '<b>Tâm bệnh</b> — do cuộc sống bất ổn, không có Trí tuệ để giải nên lo lắng nhiều → tâm loạn, u uất, bó tâm → ăn không hấp thụ được → suy nhược. Chữa: <em>“Muốn chữa bệnh ở thân thì tập cho tâm lành trước đã”</em> — tâm thánh thiện · tạo môi trường Trí tuệ · suy nghĩ tích cực · <b>tìm ra Đích Đáng Nhất cuộc đời</b> · thoát tâm', null, '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('e2157b53-60bb-5e21-a771-2c9311bc2003', 'y', '5a60858f-40d8-5c28-9a3b-fab2cfe8e55b', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Nghiệp bệnh — do tập khí nhiều kiếp → tính cách → hành động tạo nghiệp, khẩu nghiệp, ý nghiệp, oan gia trái chủ. Chữa: cầu nguyện sám hối · niệm Phật · tạo phúc trả nợ · giải nghiệp · tu luyện thân t…', null, '<b>Nghiệp bệnh</b> — do tập khí nhiều kiếp → tính cách → hành động tạo nghiệp, khẩu nghiệp, ý nghiệp, oan gia trái chủ. Chữa: cầu nguyện sám hối · niệm Phật · tạo phúc trả nợ · giải nghiệp · tu luyện thân tâm', null, '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
