insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('7eaf5e1e-20ad-5688-87db-e4d6433bf361', 'y', '45f1ffa2-dd5c-5c7c-bbd9-f7393f19ad61', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Chỉ có cốt phàm — vui là đến, đông là hùa vào, không lập trường · nghe việc gì không phân biệt được tốt xấu đúng sai · nghe câu từ Trí tuệ thì không hiểu, đau đầu, chế giễu là viển vông; nhưng nghe c…', null, '<b>Chỉ có cốt phàm</b> — vui là đến, đông là hùa vào, không lập trường · nghe việc gì không phân biệt được tốt xấu đúng sai · nghe câu từ Trí tuệ thì không hiểu, đau đầu, chế giễu là viển vông; nhưng nghe câu từ thói thường thì nhập rất nhanh', null, '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('f37e51c2-2bcb-5af6-bf10-03e59a74f9d0', 'y', '45f1ffa2-dd5c-5c7c-bbd9-f7393f19ad61', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Nghiệp nặng — cả đời không được ai nói cho nghe Trí tuệ · nghe thì hiểu lúc đó nhưng sau lại không hiểu · thấy hay nhưng sau lại không nhớ gì · hiểu nhưng quá bận rộn không có thời gian làm gì cả', null, '<b>Nghiệp nặng</b> — cả đời không được ai nói cho nghe Trí tuệ · nghe thì hiểu lúc đó nhưng sau lại không hiểu · thấy hay nhưng sau lại không nhớ gì · hiểu nhưng quá bận rộn không có thời gian làm gì cả', null, '{}'::jsonb, 3, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('95b8fc97-ac38-5e7d-a63e-a071d985715a', 'y', '0a7294ae-9de3-5fb0-9964-364935e63c19', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Đức Phật dạy: “Mọi thứ phải trông chờ từ chính mình.”', null, 'Đức Phật dạy: <em>“Mọi thứ phải trông chờ từ chính mình.”</em>', null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('35ee85f5-f051-5a5b-bd3b-6417fe501b56', 'y', 'b4eb7f7a-01ec-5e73-a9d5-dccaf199b21b', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Họa ≠ Nhân quả — Họa: cám dỗ, cạm bẫy, đồng lõa, cộng nghiệp, cảnh cuốn (đến từ ngoài). Nhân quả: do con người chủ động khởi tâm, hành động tạo ra nhân', null, '<b>Họa ≠ Nhân quả</b> — <em>Họa</em>: cám dỗ, cạm bẫy, đồng lõa, cộng nghiệp, cảnh cuốn (đến từ ngoài). <em>Nhân quả</em>: do con người chủ động khởi tâm, hành động tạo ra nhân', null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('98cd9a4a-4721-55e0-aa76-268a7926e448', 'y', 'b4eb7f7a-01ec-5e73-a9d5-dccaf199b21b', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Nhân duyên ≠ Tràn duyên — Nhân duyên: đã tạo từ quá khứ, nay đủ phúc đức thì các Ngài se lại; duyên lành hay duyên nghiệp đều là phước báu. Tràn duyên: do mình chủ động tạo ra, sẽ khiến mình mắc vào,…', null, '<b>Nhân duyên ≠ Tràn duyên</b> — <em>Nhân duyên</em>: đã tạo từ quá khứ, nay đủ phúc đức thì các Ngài se lại; duyên lành hay duyên nghiệp đều là phước báu. <em>Tràn duyên</em>: do mình chủ động tạo ra, sẽ khiến mình mắc vào, không diệt trừ được thì không giải thoát được', null, '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('8026e5c5-6b7e-5a50-9ffd-66d4233d9706', 'y', 'b4eb7f7a-01ec-5e73-a9d5-dccaf199b21b', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Tùy duyên ≠ Vô tâm — Tùy duyên: đã khởi tâm mạnh mẽ, đã phát tâm hành động chuẩn theo Trí tuệ rồi mới tùy duyên với kết quả. Vô tâm: không khát vọng, không khởi tâm cầu, không hành động, chỉ ngồi chờ…', null, '<b>Tùy duyên ≠ Vô tâm</b> — <em>Tùy duyên</em>: <b>đã khởi tâm mạnh mẽ, đã phát tâm hành động chuẩn theo Trí tuệ</b> rồi mới tùy duyên với kết quả. <em>Vô tâm</em>: không khát vọng, không khởi tâm cầu, không hành động, chỉ ngồi chờ, không đạt thì tưởng là tùy duyên', null, '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('f7e934df-44c8-571f-9eda-977d34b1c7f8', 'y', 'b4eb7f7a-01ec-5e73-a9d5-dccaf199b21b', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Tu tập ≠ Kính lễ — xem Phần 3', null, '<b>Tu tập ≠ Kính lễ</b> — xem Phần 3', null, '{}'::jsonb, 3, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('e42689fc-abba-5471-8242-c78f2c4f1c05', 'y', 'b4eb7f7a-01ec-5e73-a9d5-dccaf199b21b', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Tu sửa thân–tâm–khẩu–ý ≠ Tu thân–tâm — Tu sửa: sửa những gì đang tạo nghiệp. Tu thân–tâm: nấc cao hơn sau khi đã sửa xong — tu thân cho sạch sẽ, thanh tịnh, nhẹ nhàng, thư thái, ung dung, tự tại; tu …', null, '<b>Tu sửa thân–tâm–khẩu–ý ≠ Tu thân–tâm</b> — <em>Tu sửa</em>: sửa những gì đang tạo nghiệp. <em>Tu thân–tâm</em>: nấc cao hơn sau khi đã sửa xong — tu thân cho sạch sẽ, thanh tịnh, nhẹ nhàng, thư thái, ung dung, tự tại; tu tâm cho định tâm, trụ tâm, hoan hỷ, xả bỏ, từ bi', null, '{}'::jsonb, 4, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('11c82cdd-4d16-5561-b05c-4975eb337473', 'y', '8399665d-496c-5889-ae47-c80fa1fcd9f4', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Chức năng — làm tròn việc mình cần làm. Trong gia đình: kiếm tiền · đi chợ · nấu ăn · rửa bát · quét nhà dọn dẹp · giặt quần áo · chăm sóc con', null, '<b>Chức năng</b> — làm tròn việc mình cần làm. <em>Trong gia đình</em>: kiếm tiền · đi chợ · nấu ăn · rửa bát · quét nhà dọn dẹp · giặt quần áo · chăm sóc con', null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('f074a6d4-a42b-5a15-b8f7-883732b6a77a', 'y', '8399665d-496c-5889-ae47-c80fa1fcd9f4', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Vai trò — đảm nhiệm việc gì thì nghiên cứu, suy ngẫm để làm tốt nhất, khiến người khác hoan hỷ và mang lại lợi lạc', null, '<b>Vai trò</b> — đảm nhiệm việc gì thì nghiên cứu, suy ngẫm để làm tốt nhất, khiến người khác hoan hỷ và mang lại lợi lạc', null, '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('9ce116de-e404-5bec-95e7-7bcd5fe94185', 'y', '8399665d-496c-5889-ae47-c80fa1fcd9f4', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Bổn phận — trong gia đình: làm con, làm vợ, làm chồng, làm bố, làm mẹ. Trong công việc: lãnh đạo hay nhân viên. Với đất nước: công dân hay công chức', null, '<b>Bổn phận</b> — trong gia đình: làm con, làm vợ, làm chồng, làm bố, làm mẹ. Trong công việc: lãnh đạo hay nhân viên. Với đất nước: công dân hay công chức', null, '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('5d9acddc-781b-5eb1-b683-20dda63ee04d', 'y', '8399665d-496c-5889-ae47-c80fa1fcd9f4', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Trách nhiệm — làm đến khi xong việc mới thôi. Trách nhiệm càng cao thì tâm từ bi càng lớn', null, '<b>Trách nhiệm</b> — làm đến khi xong việc mới thôi. <b>Trách nhiệm càng cao thì tâm từ bi càng lớn</b>', null, '{}'::jsonb, 3, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('866aa248-8908-5eb0-bafe-a5e4a40d2f3e', 'y', '8399665d-496c-5889-ae47-c80fa1fcd9f4', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Nghĩa vụ (ngoài chức năng) — việc thể hiện nghĩa cử, nghĩa đạo, bắt buộc mình phải làm để báo ơn và trả nợ các điểm tựa, không phân cho ai khác được', null, '<b>Nghĩa vụ</b> (ngoài chức năng) — việc thể hiện nghĩa cử, nghĩa đạo, <b>bắt buộc mình phải làm</b> để báo ơn và trả nợ các điểm tựa, <b>không phân cho ai khác được</b>', null, '{}'::jsonb, 4, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('943e4907-d7e9-52e0-9cda-e5e9cb057d73', 'y', '1fba5d16-f8f6-5541-a111-0727d1d2155a', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Cha Mẹ và các Ngài thử tâm — dấu hiệu: 9 cửa đóng, 1 cửa mở. Ứng: hoan hỷ + nhìn đa chiều để tinh tấn nhận ra cửa sinh', null, '<b>Cha Mẹ và các Ngài thử tâm</b> — dấu hiệu: <b>9 cửa đóng, 1 cửa mở</b>. Ứng: hoan hỷ + nhìn đa chiều để tinh tấn <b>nhận ra cửa sinh</b>', null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('c3914f1d-3d26-50d8-9315-c9b2df9ba6c5', 'y', '1fba5d16-f8f6-5541-a111-0727d1d2155a', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Ma Chướng phá — dấu hiệu: tất cả các cửa đều đóng. Ứng: luôn định tâm và làm đúng luật. Lùi một bước để tiến ba bước', null, '<b>Ma Chướng phá</b> — dấu hiệu: <b>tất cả các cửa đều đóng</b>. Ứng: luôn <b>định tâm</b> và <b>làm đúng luật</b>. <b>Lùi một bước để tiến ba bước</b>', null, '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
