insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('305bcc02-bbef-589b-a2c0-35b655caddae', 'y', '06779147-6998-5137-901e-06136786197c', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, '5 hành động của tâm từ bi: yêu thương · quan tâm · giúp đỡ · bảo vệ · giữ gìn — cho mình và người khác', null, '<b>5 hành động của tâm từ bi</b>: yêu thương · quan tâm · giúp đỡ · bảo vệ · giữ gìn — cho mình và người khác', null, '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('5d517c1b-be93-5bb7-bfd6-c7fc3785b1b5', 'y', '46dc7102-ccda-5ad9-8bce-d79b75f40ec7', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Rà soát để định vị phúc nghiệp · tìm góc độ tác động chính · biết bất ổn tiềm ẩn để chủ động trả nghiệp trước · biết dương phần và âm phần tốt hay kém', null, 'Rà soát để <b>định vị phúc nghiệp</b> · tìm góc độ tác động chính · biết bất ổn tiềm ẩn để chủ động trả nghiệp trước · biết <b>dương phần và âm phần</b> tốt hay kém', null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('8ec90b7c-b49a-567d-8c53-bf50d24f9c3b', 'y', '46dc7102-ccda-5ad9-8bce-d79b75f40ec7', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Phương pháp: quy chiếu vào quy chuẩn của Trí tuệ để trả lời câu hỏi rà soát — không rà soát theo tư duy. Ví dụ: để trả lời “thờ tự có chuẩn không” thì quy chiếu vào 4 ý — Thờ cúng chuẩn · Gốc Phật · …', null, '<b>Phương pháp</b>: quy chiếu vào <b>quy chuẩn của Trí tuệ</b> để trả lời câu hỏi rà soát — không rà soát theo tư duy. <em>Ví dụ: để trả lời “thờ tự có chuẩn không” thì quy chiếu vào 4 ý — Thờ cúng chuẩn · Gốc Phật · Lễ Nghi · Gia quy</em>', null, '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('378e07b6-a4c8-5d5f-b506-bd1a2ebffb33', 'y', '46dc7102-ccda-5ad9-8bce-d79b75f40ec7', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Rà soát gia tiên: nghề nghiệp (có làm nghề sát sinh không? có làm quan xử sai cho ai chết oan không?) · cách sống (có làm phúc không? có phá đền chùa? có ăn trộm của chùa, của đất nước, của người khá…', null, '<b>Rà soát gia tiên</b>: nghề nghiệp (có làm nghề sát sinh không? có làm quan xử sai cho ai chết oan không?) · cách sống (có làm phúc không? có phá đền chùa? có ăn trộm của chùa, của đất nước, của người khác? có nuôi âm binh? có làm thầy cúng hình nhân thế mạng?) · Hiếu–Lễ–Nghĩa (có đưa tâm thờ tự không? thờ tự có chuẩn mực không?)', null, '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
