insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('9ce42d36-44d5-5cd0-a0ad-46e31aee4fe8', 'y', 'd8bf3833-ece1-54ae-98f8-53423d59a039', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Hành thiện — phát tâm bồ đề theo thực tế thời điểm. Không có kế hoạch trước · không cần tấu trình, Trời Phật chứng tâm và ban phúc luôn · tiền lấy từ khoản chi tiêu cá nhân · có thể làm cho người thâ…', null, '<b>Hành thiện</b> — phát tâm bồ đề <em>theo thực tế thời điểm</em>. Không có kế hoạch trước · <b>không cần tấu trình</b>, Trời Phật chứng tâm và ban phúc luôn · tiền lấy từ khoản <b>chi tiêu cá nhân</b> · <b>có thể làm cho người thân, họ hàng</b>', null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('9ed28ae0-50ab-5851-9810-01e601d44d79', 'y', 'd8bf3833-ece1-54ae-98f8-53423d59a039', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Tạo phúc, trả nợ — là bổn phận, trách nhiệm. Có kế hoạch, định kỳ 6 tháng/lần · phải tấu trình trước và báo cáo sau · tiền lấy từ khoản tạo phúc trả nợ · phải làm ra ngoài cộng đồng, không làm cho ng…', null, '<b>Tạo phúc, trả nợ</b> — là <em>bổn phận, trách nhiệm</em>. Có kế hoạch, <b>định kỳ 6 tháng/lần</b> · <b>phải tấu trình</b> trước và báo cáo sau · tiền lấy từ khoản <b>tạo phúc trả nợ</b> · <b>phải làm ra ngoài cộng đồng</b>, không làm cho người trong họ', null, '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('5ec0f6d5-02e3-523e-b52d-a45589acc07d', 'y', 'ab0b7b77-8900-5b50-bd44-05a9c6370ff6', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Hành 7 đạo mọi lúc mọi nơi — thấy người khác hành xử lỗi đạo thì trung trực chia sẻ để họ sửa. Cần tinh tế xét thực tế xem người nào chia sẻ được, người nào không, tránh để lại ân oán', null, '<b>Hành 7 đạo mọi lúc mọi nơi</b> — thấy người khác hành xử lỗi đạo thì trung trực chia sẻ để họ sửa. Cần tinh tế xét thực tế xem người nào chia sẻ được, người nào không, tránh để lại ân oán', null, '{}'::jsonb, 0, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('d9f923da-747f-55ed-9e8f-f21ea7e196b9', 'y', 'ab0b7b77-8900-5b50-bd44-05a9c6370ff6', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Khai tuệ — với người chưa biết Trí tuệ: chia sẻ các ý trong 7 ý thực tế · khai thác các ý Trí tuệ · dùng nới rộng hiểu biết để định hướng tư tưởng họ tiếp cận dần', null, '<b>Khai tuệ</b> — với người chưa biết Trí tuệ: chia sẻ các ý trong 7 ý thực tế · khai thác các ý Trí tuệ · dùng nới rộng hiểu biết để định hướng tư tưởng họ tiếp cận dần', null, '{}'::jsonb, 1, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
insert into public.nut (id, loai, cha_id, module_id, ma, tieu_de, tom_tat, noi_dung, nhan, du_lieu, thu_tu, pham_vi, trang_thai) values ('cdb6801b-bfc3-5808-a627-b5cf09ab91c8', 'y', 'ab0b7b77-8900-5b50-bd44-05a9c6370ff6', '486cdc6d-3902-5eb6-ae1e-991b35918e15', null, 'Hành Bồ tát đạo — không phải bất chấp thực tế lao ra làm mọi việc, mà là giúp người trần biết đến Trí tuệ và giúp vong linh siêu thoát. Để hành được thì trước hết bản thân phải tu đức — có đức mới độ…', null, '<b>Hành Bồ tát đạo</b> — không phải bất chấp thực tế lao ra làm mọi việc, mà là giúp người trần biết đến Trí tuệ và giúp vong linh siêu thoát. <b>Để hành được thì trước hết bản thân phải tu đức — có đức mới độ được cho người khác</b>', null, '{}'::jsonb, 2, 'thanh_vien'::public.pham_vi, 'xuat_ban'::public.trang_thai_nd)
